FROM (select 'Coming Soon' as dummy_value) AS "finsights_capital_dummy"

/* cppi::d795ee1dad7017e53bfd7a8dae8b5c6e2edfe9bdfd73cf2dc89d48b84b675ce1 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-14' and end_date = '2025-05-14')
and start_date = '2025-05-14' and end_date = '2025-05-14'

